(selectors) => {
  const roots = [];
  for (const sel of selectors) document.querySelectorAll(sel).forEach(n => roots.push(n));
  // 에셋 컨테이너가 없으면(자체 CDN 리테일러 — Amazon/Coolblue 등은 해시 클래스라 고정
  // 셀렉터가 안 맞는다) 크롬(헤더/내비/푸터) 제외한 body 텍스트로 폴백한다. SB 경로
  // (core.official_style._CAPTURE_INJECT)와 동일 계약 — 안 그러면 로컬 크롤 건만
  // asset_text 가 빈 값이 되어 ID31 이 블록 캡션 폴백으로 떨어진다(일치율 과소평가).
  if (!roots.length) {
    const clone = document.body.cloneNode(true);
    clone.querySelectorAll('header,nav,footer,aside,[role=banner],[role=navigation],[role=contentinfo]')
      .forEach(n => n.remove());
    return (clone.innerText || '').slice(0, 30000);
  }
  return roots.map(r => r.innerText || '').join('\n').slice(0, 30000);
}

(selectors) => {
  const out = {truncated: [], broken_images: [], carousel_overlaps: []};
  const roots = [];
  for (const sel of selectors) document.querySelectorAll(sel).forEach(n => roots.push(n));
  const seenT = new Set(), seenI = new Set();
  // 같은 URL이 페이지에 중복 삽입되는 경우(히어로 이미지 + 탭/선택 아이콘 등, flix
  // 위젯에 흔함) 한쪽 인스턴스만 로드 실패하는 걸 실측했다(2026-07-31, Darty
  // F20F12BST: 같은 motion.webp가 큰 이미지로는 정상 로드·아이콘 인스턴스는 실패,
  // 30초 대기해도 안정적으로 재현 — 격리 렌더가 CSS 없이 아이콘을 의도치 않은
  // 크기로 렌더해 200px 필터도 못 거른다). URL 자체가 실제로 깨졌다면 **모든**
  // 인스턴스가 실패해야 한다 — 어느 한 곳이라도 로드에 성공했다면 그 URL은 깨진
  // 게 아니라는 가장 직접적인 증거다. 그래서 먼저 전 root에서 로드 성공 URL을
  // 모으고, 그 목록에 있는 URL은 깨짐 판정에서 제외한다.
  // ⚠️ 프로토콜 표기 정규화 필수 — 같은 리소스라도 승격된(promoted) 인스턴스는
  // currentSrc 가 절대경로(https://...)인 반면, 실패한 인스턴스는 currentSrc 가
  // 비어 원본 속성 그대로인 프로토콜 상대경로(//...)로 폴백된다(격리 렌더는
  // about:blank 라 // 를 해석할 기준 프로토콜이 없어 이 인스턴스만 로드 실패 —
  // 실서비스 페이지에선 정상 로드될 URL). 정규화 없인 두 표기가 다른 문자열이라
  // Set 매칭이 실패한다(2026-07-31 Darty F20F12BST 재현: 동일 motion.webp 6건).
  const normU = u => (u || '').replace(/^https?:/, '');
  const loadedOk = new Set();
  for (const root of roots) {
    root.querySelectorAll('img').forEach(img => {
      if (img.complete && img.naturalWidth > 0) {
        const u = img.currentSrc || img.src || '';
        if (u) loadedOk.add(normU(u));
      }
    });
  }
  for (const root of roots) {
    root.querySelectorAll('*').forEach(el => {
      const cs = getComputedStyle(el);
      // 텍스트 잘림: ellipsis 처리 + 실제 넘침
      if (cs.textOverflow === 'ellipsis' && el.scrollWidth > el.clientWidth + 1) {
        const t = (el.innerText || '').trim().slice(0, 80);
        if (t && !seenT.has(t)) { seenT.add(t); out.truncated.push(t); }
      }
    });
    root.querySelectorAll('img').forEach(img => {
      // 이미지 깨짐: 로드 완료됐는데 naturalWidth 0. naturalWidth 가 0 이라 크기를
      // 못 재니 **렌더 박스**(CSS/HTML 지정 크기)로 UI 아이콘·썸네일을 배제한다. 기준은
      // core.eval.MIN_CONTENT_IMG_PX(200) 와 동일 — 2026-07-31 실측: PDF/다운로드
      // SVG 아이콘·로딩 스피너가 naturalWidth 0 으로 잡혀 위결함이었다(실제론 정상
      // 로드됨, httpx 직접조회 200 확인).
      // ⚠️ 0×0(렌더 박스 자체가 없음)도 배제 대상 — CSS 클래스 의존 요소가 그 스타일시트
      // 없이(격리 렌더 등) 삽입되면 정확히 0×0 이 되고 네트워크 요청조차 안 간다(같은
      // 실측: flix delivery 격리 렌더의 .flix-adobe-icon). 반면 **크기 지정 없이 진짜
      // 깨진** 이미지는 브라우저 기본 깨짐 아이콘(~22px)으로 렌더돼 0이 아닌 작은 양수가
      // 나온다 — 그래서 "0×0"과 "작은 양수"를 구분할 필요 없이 200px 미만이면 전부
      // 배제해도 true positive(큰 콘텐츠 이미지)는 안 죽는다.
      if (img.complete && img.naturalWidth === 0) {
        const r = img.getBoundingClientRect();
        if (Math.max(r.width, r.height) < 200) return;
        const u = img.currentSrc || img.src || '';
        if (u && loadedOk.has(normU(u))) return;   // 다른 인스턴스가 로드 성공 → 이 URL은 안 깨짐
        if (u && !seenI.has(u)) { seenI.add(u); out.broken_images.push(u); }
      }
    });
  }
  // 캐러셀 네비 버튼 겹침 (2026-07-24 보수 구현 — 검출 로직 미검증, 재현 케이스 미확보).
  // 버튼끼리의 겹침만 센다: 화살표가 슬라이드(이미지) 위에 얹히는 건 정상 캐러셀 디자인이라
  // 콘텐츠와의 겹침을 세면 전 행 위결함이 된다. 이중 렌더로 같은 자리에 버튼이 포개진
  // 증상(연동 오류 추정)만 잡는다. 겹침은 해상도 종속 — 기준은 크롤 뷰포트(1280×720 잠정).
  const NAV_RE = /(carousel|slider|slick|swiper|splide|glide|flix)[\w-]*(prev|next|arrow|nav|control|button)|(prev|next|arrow)[\w-]*(carousel|slider|slick|swiper|flix)|\b(slick|swiper)-(prev|next|arrow)/i;
  const btnSeen = new Set(), btns = [];
  const label = el => (el.tagName.toLowerCase() + '.'
                       + ((el.getAttribute('class') || el.getAttribute('aria-label') || '')
                          .trim().split(/\s+/).slice(0, 3).join('.'))).slice(0, 80);
  for (const root of roots) {
    root.querySelectorAll('button, [role="button"], a').forEach(el => {
      if (btnSeen.has(el)) return;                       // 루트 셀렉터 중복 매칭 방지
      const sig = (el.getAttribute('class') || '') + ' ' + (el.getAttribute('aria-label') || '');
      if (!NAV_RE.test(sig)) return;
      const r = el.getBoundingClientRect();
      if (r.width < 10 || r.height < 10) return;         // display:none/접힘 → rect 0
      if (getComputedStyle(el).visibility === 'hidden') return;
      btnSeen.add(el); btns.push({el, r});
    });
  }
  for (let i = 0; i < btns.length; i++) {
    for (let j = i + 1; j < btns.length; j++) {
      const a = btns[i], b = btns[j];
      if (a.el.contains(b.el) || b.el.contains(a.el)) continue;   // 중첩 마크업은 겹침 아님
      const w = Math.min(a.r.right, b.r.right) - Math.max(a.r.left, b.r.left);
      const h = Math.min(a.r.bottom, b.r.bottom) - Math.max(a.r.top, b.r.top);
      if (w <= 0 || h <= 0) continue;
      const inter = w * h;
      const minArea = Math.min(a.r.width * a.r.height, b.r.width * b.r.height);
      const pct = Math.round(inter / minArea * 100);
      if (pct >= 30)                                      // 작은 스침은 디자인 여지 — 보수 임계
        out.carousel_overlaps.push({a: label(a.el), b: label(b.el), overlap_pct: pct});
    }
  }
  return out;
}

(selectors) => {
  const out = [];
  const roots = [];
  for (const sel of selectors) document.querySelectorAll(sel).forEach(n => roots.push(n));
  for (const root of roots) {
    root.querySelectorAll('img').forEach(img => {
      const r = img.getBoundingClientRect();
      if (r.width < 2 || r.height < 2) return;
      out.push({kind: 'image', box: [r.x, r.y, r.width, r.height],
                url: img.currentSrc || img.src || ''});
    });
    root.querySelectorAll('*').forEach(el => {
      const text = Array.from(el.childNodes)
        .filter(n => n.nodeType === 3)
        .map(n => n.textContent)
        .join(' ')
        .trim();
      if (!text) return;
      const r = el.getBoundingClientRect();
      if (r.width < 2 || r.height < 2) return;
      const cs = getComputedStyle(el);
      out.push({kind: 'text', box: [r.x, r.y, r.width, r.height],
                text,
                font_size: parseFloat(cs.fontSize) || 0,
                align: cs.textAlign, color: cs.color,
                border_width: cs.borderTopWidth, border_style: cs.borderTopStyle});
    });
  }
  return out;
}

() => {
  const out = [];
  document.querySelectorAll('video').forEach(v => {
    const s = v.currentSrc || v.src ||
      (v.querySelector('source') ? (v.querySelector('source').src || v.querySelector('source').getAttribute('src') || '') : '');
    out.push({kind:'video', src:s, error: v.error ? v.error.code : null,
              readyState: v.readyState, networkState: v.networkState});
  });
  document.querySelectorAll('iframe').forEach(f => {
    const s = f.src || '';
    if (/youtube|youtu\.be|vimeo|flixcar|brightcove|cliplister|player/i.test(s))
      out.push({kind:'embed', src:s, error:null, readyState:null, networkState:null});
  });
  // 클릭형 팝업 비디오 — 플레이어는 클릭 후에만 뜨고 DOM 엔 비디오 서비스 썸네일만 있다
  // (2026-07-14 실측: MediaMarkt Cliplister 썸네일 4개·refs 17개인데 video/iframe 0 →
  // "영상 있는데 0"). 알려진 비디오 CDN 썸네일을 '존재 관측'으로 센다.
  document.querySelectorAll('img').forEach(im => {
    const u = im.currentSrc || im.src || '';
    if (/cliplister|img\.youtube\.com\/vi\/|i\.ytimg\.com|vimeocdn/i.test(u))
      out.push({kind:'popup', src:u, error:null, readyState:null, networkState:null});
  });
  return out;
}

() => {
  const LAZY = ['data-flixsrcset', 'data-srcset', 'data-src', 'data-lazy-src'];
  const abs = u => (u || '').startsWith('//') ? 'https:' + u : u;
  const first = v => (v || '').split(',')[0].trim().split(' ')[0];
  let n = 0;
  document.querySelectorAll('img').forEach(im => {
    for (const a of LAZY) {
      const d = im.getAttribute(a);
      if (d && (!im.src || im.src.includes('loading') || im.src.startsWith('data:'))) {
        im.src = abs(first(d)); im.removeAttribute('srcset'); n++; break;
      }
    }
  });
  return n;
}

() => {
  const CHROME = 'header,nav,footer,aside,[role=banner],[role=navigation],[role=contentinfo]';
  const out = [];
  document.querySelectorAll('img').forEach(img => {
    if (img.closest(CHROME)) return;
    const r = img.getBoundingClientRect();
    if (r.width < 40 || r.height < 40) return;   // 아이콘/썸네일 배제
    out.push({kind: 'image', box: [r.x, r.y, r.width, r.height],
              url: img.currentSrc || img.src || ''});
  });
  document.querySelectorAll('*').forEach(el => {
    if (el.closest(CHROME)) return;
    const text = Array.from(el.childNodes)
      .filter(n => n.nodeType === 3).map(n => n.textContent).join(' ').trim();
    if (!text || text.length > 160) return;      // 롱카피(스펙표·리뷰 본문) 배제
    const r = el.getBoundingClientRect();
    if (r.width < 2 || r.height < 2) return;
    const cs = getComputedStyle(el);
    out.push({kind: 'text', box: [r.x, r.y, r.width, r.height], text,
              font_size: parseFloat(cs.fontSize) || 0,
              align: cs.textAlign, color: cs.color,
              border_width: cs.borderTopWidth, border_style: cs.borderTopStyle});
  });
  return out;
}
